class TestCheckModel(unittest.TestCase):
    # assign & mock/mockito
    # Java:
    #           Model mockModel = mock(Model())/some object;
    #           String mockString = "blabla";
    #           Pass    ->  when(blaService.loadModel(mockString)).thenReturn(mockModel);
    #           Error   ->  when(onnxLoader.load(mockFile)).thenThrow(new FileNotFoundException());
    #           Verify  ->  verify(mockString).loadModel(mockModel)

    #
    # Pyhon:
    #           mock_model = MagicMock()
    #           mock_string = "blabla"
    #                                   file.import.method? -> patch is for mocking
    #           Pass    ->  with patch("helpers.onnx.load", return_value=mock_model): check_model(model_file=mock_string)
    #           Error   ->  with patch("helpers.onnx.load", side_effect=FileNotFoundException):
    #           Verify  ->  mock_load.assert_called_once_with(mockFile)

    # Assing & mocks
    mock_model_name = "mil-yolov26n.onnx"

    def test_model_name_raises_type_error_when_not_a_str(self):
        with self.assertRaises(TypeError):
            check_model(model_name=1)

    def test_model_name_raises_type_error_when_not_onnx_format(self):
        with self.assertRaises(TypeError):
            check_model(model_name="oogabooga.onn")

    def _make_mock_model(self, metadata: dict):
        """Helper: builds a mock onnx model with the given metadata dict."""
        mock_model = MagicMock()
        mock_model.metadata_props = [
            MagicMock(key=k, value=v) for k, v in metadata.items()
        ]
        return mock_model

    def test_raises_file_not_found_when_file_missing(self):
        with patch("helpers.load", side_effect=FileNotFoundError):
            with self.assertRaises(FileNotFoundError):
                check_model(model_file="nonexistent.onnx")

    def test_raises_value_error_when_file_is_not_valid_onnx(self):
        with patch("helpers.load", side_effect=DecodeError):
            with self.assertRaises(ValueError):
                check_model(model_file="corrupt.onnx")

    def test_raises_key_error_when_names_missing(self):
        mock_model = self._make_mock_model({"imgsz": "[480, 480]"})
        with patch("helpers.load", return_value=mock_model):
            with self.assertRaises(KeyError):
                check_model(model_file="fake.onnx")

    def test_raises_key_error_when_imgsz_missing(self):
        mock_model = self._make_mock_model({"names": "['cat', 'dog']"})
        with patch("helpers.load", return_value=mock_model):
            with self.assertRaises(KeyError):
                check_model(model_file="fake.onnx")

    def test_returns_correct_image_size_and_labels(self):
        mock_model = self._make_mock_model(
            {"imgsz": "[480, 480]", "names": "{1:'cat', 2:'dog', 3:'car'}"}
        )
        with patch("helpers.load", return_value=mock_model):
            image_size, labels = check_model(model_file=self.mock_model_name)

        self.assertEqual(image_size, 480)
        self.assertEqual(labels, {1: "cat", 2: "dog", 3: "car"})


