    def test_binary_str_not_a_string(self):
        with self.assertRaises(TypeError):
            binary_str_to_numpy_array(1)

    def test_binary_str_not_correct_binary_file_extension(self):
        with self.assertRaises(TypeError):
            binary_str_to_numpy_array("F69j/")

    def test_binary_str_raises_binascii_error_non_valid_characters(self):
        with self.assertRaises(BinasciError):
            binary_str_to_numpy_array("iVBORwt\n\t")

    def test_binary_str_raises_value_error_too_few_characters(self):
        with patch("helpers.frombuffer", side_effect=ValueError):
            with self.assertRaises(ValueError):
                binary_str_to_numpy_array("/9j/AA==")

    def test_binary_str_passed(self):
        result = binary_str_to_numpy_array(self.mock_file_as_a_string)
        expected = frombuffer(self.mock_machine_string, uint8)
        testing.assert_array_equal(result, expected)

    def test_imdecode_returns_none_for_corrupt_data(self):
        corrupt_array = frombuffer(b"\xff\xd8\xff" + b"\x00" * 10, uint8)
        with self.assertRaises(ValueError):
            retrive_numpy_array_image_for_model_inference(corrupt_array)

    def test_cv2_raises_cv_error(self):
        with patch("helpers.resize", side_effect=CVError):
            with self.assertRaises(ValueError):
                retrive_numpy_array_image_for_model_inference(self.numpy_array_img)

